#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.Managers;
using MVZ2Logic;
using MVZ2Logic.Contraptions;
using MVZ2Logic.Customize;
using MVZ2Logic.Inputs;
using MVZ2Logic.Models;
using MVZ2Logic.Saves;
using PVZEngine;
using PVZEngine.Level;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.EventSystems;

namespace MVZ2.Customize
{
    public class TeleporterTeamController : CustomizePageController
    {
        public override void Display(Camera camera)
        {
            uiCamera = camera;
            LoadTeam();
            LoadBlueprints();
            gameObject.SetActive(true);
        }
        public override void Hide()
        {
            gameObject.SetActive(false);
        }
        #region 生命周期
        private void Awake()
        {
            ui.OnBlueprintClick += OnBlueprintSelectCallback;
            ui.OnConfirmClick += OnConfirmClickCallback;
            ui.OnCancelClick += OnCancelClickCallback;
        }
        #endregion

        #region 事件回调
        private void OnBlueprintSelectCallback(int index, PointerEventData pointerData)
        {
        }
        private void OnConfirmClickCallback()
        {
            SaveTeam();
            Return();
        }
        private void OnCancelClickCallback()
        {
            Return();
        }
        #endregion
        private void LoadTeam()
        {
            var team = Global.Saves.GetTeleporterTeam() ?? DefaultTeam;
            currentTeleporterTeam = team;
            SetUITeam(team);
        }
        private void SetUITeam(TeleporterTeam team)
        {
            ui.SetLayoutTileCount(MAX_TILE_COUNT);
            ui.ClearTiles();
            var tileIndexes = team.GetTileIndexes();
            foreach (var index in tileIndexes)
            {
                var tile = team.GetTile(index);
                if (tile == null)
                    continue;
                foreach (var ent in tile.GetEntities())
                {
                    var entDefinition = Global.Game.GetEntityDefinition(ent);
                    if (entDefinition == null)
                        continue;
                    var modelID = entDefinition.GetModelID();
                    var modelBuilder = ModelFactories.GetModelBuilder(modelID, uiCamera.Exists() ? uiCamera : Camera.main);
                    if (modelBuilder == null)
                        continue;
                    ui.AddTileEntity(index, ent, modelBuilder);
                }
            }
        }

        private void SaveTeam()
        {
            Global.Saves.SetTeleporterTeam(currentTeleporterTeam);
            Global.Saves.SaveToFile();
        }
        private void LoadBlueprints()
        {
            var mobile = Main.UseMobileLayout();
            contraptionEntries.Clear();
            Main.AlmanacManager.GetContraptionPageEntries(contraptionEntries);

            var contraptionViewDatas = contraptionEntries.Select(c => Main.AlmanacManager.GetChoosingBlueprintViewData(c, false)).ToArray();
            ui.SetBlueprintDisplayerPlatform(mobile);
            ui.SetBlueprintEntries(mobile, contraptionViewDatas);
        }
        public static TeleporterTeam CreateDefaultTeleporterTeam()
        {
            // TODO: 改为Teleporter_Evoke。
            var team = new TeleporterTeam();
            team.AddTileEntity(1, new NamespaceID("mvz2", "furnace"));
            team.AddTileEntity(3, new NamespaceID("mvz2", "furnace"));
            team.AddTileEntity(5, new NamespaceID("mvz2", "furnace"));
            team.AddTileEntity(7, new NamespaceID("mvz2", "furnace"));
            return team;
        }

        public static MainManager Main => MainManager.Instance;
        public const int MAX_TILE_COUNT = 9;
        public static readonly TeleporterTeam DefaultTeam = CreateDefaultTeleporterTeam(); // TODO: 改为Teleporter_Evoke。
        [SerializeField]
        private TeleporterTeamUI ui = null!;
        private Camera? uiCamera;
        private TeleporterTeam? currentTeleporterTeam;
        private readonly List<NamespaceID?> contraptionEntries = new List<NamespaceID?>();
    }
}
